// TestPlaybackCapabilityGateJoint — playback-capability-gate box 5.1, the
// Tier-1 joint over the change's three cross-group contracts, every hop a
// real instance (real scanner subprocesses persisting real ffprobe facts,
// the real enrich streams lane with the gate-closure composition root's
// wiring, real ffmpeg pack, real stream.Service, real api router over real
// HTTP; no mocks). cmd/mellifera is package main and cannot be imported, so
// its PackItem/AfterPackPersist/Play closures are mirrored here in miniature
// (the pbNewWorld house pattern) — the decisions they JOIN are the production
// functions: stream.PackGate, refusal.PolicyRefusal handling, refusal.PlayRefusal
// mapping, stream.EvictSuperseded.
//
//   - (a) end-to-end codecs (2.1's record ≡ 2.2's projection ≡ the artifact
//     truth): a real pack through the real lane publishes, and the descriptor
//     GET through the REAL router answers mode hls whose `codecs` array is
//     byte-identical to (i) the record persisted in doc["streams"].codecs and
//     (ii) an in-test ffprobe ORACLE of the published build — the served
//     playlist's EXT-X-MAP init segment's sample entries (avc1/mp4a tags,
//     probed verbatim) with profile/level read from the published playlist
//     and composed through the RFC 6381 constants restated in the test. A
//     direct answer in the same session carries no `codecs` key at all.
//   - (b) publish replacement (4.1's seam over the real lane): repacking the
//     same item through the real EnqueuePack seam publishes a fresh nonce,
//     and the ON-DISK state (directory listing, never a log line) keeps
//     exactly ONE build directory — the nonce the descriptor then answers;
//     the superseded playlist URL stops answering.
//   - (c) gate refusal (1.2's refusal.PlayRefusal): a knob-off opt-in item
//     answers the descriptor's own `codec_not_opted_in` token while its
//     state is none (the honesty projection), and once its packaging state
//     is failed (seeded through the store, the lane's terminal shape) the
//     SAME token rides POST /play {retry:true} back as a 400 code through
//     the real router — one judge, one vocabulary — leaving the failed state
//     untouched and nothing enqueued.
//
// Coverage referenced, not re-proven: the composition table's cases
// (stream/codecs_test.go, 2.1), the projection units
// (stream/describe_codecs_test.go, 2.2), the eviction edge cases
// (stream/evict_test.go, 4.1), the refusal handler mapping incl. the
// unsupported token and the nothing_failed twin
// (api/playback_test.go TestPlayGateRefusal, 1.2), the SPA probe (3.1's
// vitest), budget-pressure eviction (the orchestrator suite).
package itest

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/enrich"
	"github.com/mellifera/mellifera/internal/refusal"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/internal/stream"
	"github.com/mellifera/mellifera/internal/web"
)

// gateDescriptor is the descriptor wire shape decoded from the SERVED bytes —
// state_reason and codecs stay raw so the test asserts the wire's
// presence/absence exactly as the SPA consumes them (a typed nil slice would
// silently accept a JSON null; a missing key must read as absent).
type gateDescriptor struct {
	Mode        string          `json:"mode"`
	State       string          `json:"state"`
	PlayURL     string          `json:"play_url"`
	StateReason json.RawMessage `json:"state_reason"`
	Codecs      json.RawMessage `json:"codecs"`
}

// gateNewQueue is pbNewQueue's composition root with the change's two wiring
// lines added (cmd/mellifera main.go in miniature): the PackItem closure
// judges the build-time gate first (a closed verdict returns
// refusal.PolicyRefusal — the lane's policy branch, never the failure ledger),
// and AfterPackPersist is the real EvictSuperseded (publish replacement).
func gateNewQueue(t *testing.T, w *pbWorld) *enrich.Queue {
	t.Helper()
	deps := enrich.Deps{Store: w.st, Modules: w.reg, Plugins: w.mgr}
	deps.PackItem = func(ctx context.Context, itemID, absPath string, ffprobe map[string]any, voiceovers []string) (enrich.PackOutcome, error) {
		if gate := stream.PackGate(ffprobe, w.media.OptInCodecs); gate != stream.GateOpen {
			return enrich.PackOutcome{}, refusal.PolicyRefusal{Reason: string(gate)}
		}
		build, err := w.media.Pack(ctx, itemID, absPath, ffprobe, voiceovers)
		return enrich.PackOutcome{Playlist: build.Playlist, Nonce: build.Nonce, Codecs: build.Codecs}, err
	}
	deps.AfterPackPersist = w.media.EvictSuperseded
	q := enrich.NewQueue(deps, enrich.QueueConfig{Workers: 2, Backoff: time.Millisecond})
	if err := q.Start(context.Background()); err != nil {
		t.Fatalf("queue Start: %v", err)
	}
	t.Cleanup(q.Stop)
	return q
}

// gateNewServer boots a second REAL api+web router over the world's store and
// stream service, wired with the Playback closure (pbNewWorld's mirror) and
// the Play closure (main.go's retryFailedPack in miniature — the knob-off
// branch the refusal leg rides). Returns the server's base URL; w.client
// drives it like any other real server.
func gateNewServer(t *testing.T, w *pbWorld, enqueue func(string) error) string {
	t.Helper()
	apiH := api.New(api.Deps{
		AdminToken: w.token,
		Store:      w.st,
		Playback: func(ctx context.Context, itemID string) (api.Playback, error) {
			row, err := w.st.GetItem(ctx, itemID)
			if err != nil {
				return api.Playback{}, err
			}
			var doc map[string]any
			if err := json.Unmarshal(row.Document, &doc); err != nil {
				return api.Playback{}, err
			}
			mode, state, playURL, sections, voiceovers, stateReason, codecs := w.media.Describe(itemID, doc)
			tok, _ := w.media.Issue(itemID, time.Now())
			// decision_log.go's playbackDescriptor shape, minus the package-main
			// log line — Codecs rides (the pre-gate harness mirror predates the
			// field and drops it; the production closure carries it).
			return api.Playback{Mode: mode, State: state, PlayURL: playURL, StateReason: stateReason, Codecs: codecs, Sections: sections, Voiceovers: voiceovers, Token: tok}, nil
		},
		Play: func(ctx context.Context, itemID string, retry bool, _ *float64) (bool, error) {
			row, err := w.st.GetItem(ctx, itemID)
			if err != nil {
				return false, err // sql.ErrNoRows → 404 at the handler
			}
			if !retry {
				return false, nil // pack-on-play (D-8) is none of this joint's three legs
			}
			doc := map[string]any{}
			_ = json.Unmarshal(row.Document, &doc)
			streams, _ := doc["streams"].(map[string]any)
			if state, _ := streams["state"].(string); state != stream.StateFailed {
				return false, nil // nothing failed → 400 nothing_failed at the handler
			}
			ff, _ := doc["ffprobe"].(map[string]any)
			if gate := stream.PackGate(ff, w.media.OptInCodecs); gate != stream.GateOpen {
				return false, refusal.PlayRefusal{Reason: string(gate)}
			}
			if err := enqueue(itemID); err != nil {
				return false, err
			}
			return true, nil
		},
	})
	srv := httptest.NewServer(web.Handler(apiH, web.Options{Media: w.media}))
	t.Cleanup(srv.Close)
	return srv.URL
}

// gateSeedItem writes one floor file and puts one knob-off opt-in item row
// directly through the store (the pubSeedItem pattern — the honesty
// projection and the gate read stored facts only, so documents are seeded
// straight through the store): HEVC Main video + AAC audio in a Matroska
// container, the canonical codec_not_opted_in shape. The pack lane's ffmpeg
// fixtures stay h264+AAC (the six-slot's out-of-scope note) — the classifier
// admits the HEVC family from facts, no HEVC fixture is ever packed here.
func gateSeedItem(t *testing.T, w *pbWorld, libID int64, rel string) string {
	t.Helper()
	ctx := context.Background()
	floor := filepath.Join(t.TempDir(), filepath.Base(rel))
	if err := os.WriteFile(floor, []byte("floor bytes of "+rel), 0o644); err != nil {
		t.Fatalf("write floor fixture: %v", err)
	}
	doc := map[string]any{
		"parsed": map[string]any{"absolute_path": floor},
		"ffprobe": map[string]any{
			"format": map[string]any{"format_name": "matroska,webm", "duration": "5.000000"},
			"streams": []any{
				map[string]any{"codec_name": "hevc", "codec_type": "video", "profile": "Main", "pix_fmt": "yuv420p10le", "width": 128, "height": 72},
				map[string]any{"codec_name": "aac", "codec_type": "audio", "profile": "LC", "sample_rate": "44100"},
			},
		},
		"streams": map[string]any{"state": stream.StateNone},
	}
	raw, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal doc: %v", err)
	}
	fileID := fmt.Sprintf("gate%d-%s", libID, strings.ReplaceAll(rel, "/", "_"))
	itemID := fmt.Sprintf("itm_%d_%s", libID, fileID)
	err = w.st.PutItem(ctx, store.Item{
		ID: itemID, ModuleID: "serial", LibraryID: libID, FileID: fileID,
		RelativePath: rel, MediaType: "movie", Document: raw, SchemaVersion: 1,
	})
	if err != nil {
		t.Fatalf("seed item %s: %v", rel, err)
	}
	return itemID
}

// gateFailItem rewrites one item's streams namespace to the lane's terminal
// failed shape — the state a real gate-refused run persists (failedStreamsDoc
// with the policy reason). The test plays the lane's seeding role here: the
// lane is the only production writer of this namespace.
func gateFailItem(t *testing.T, w *pbWorld, itemID string) {
	t.Helper()
	ctx := context.Background()
	row, err := w.st.GetItem(ctx, itemID)
	if err != nil {
		t.Fatalf("reload item %s: %v", itemID, err)
	}
	doc := map[string]any{}
	if err := json.Unmarshal(row.Document, &doc); err != nil {
		t.Fatalf("decode doc %s: %v", itemID, err)
	}
	doc["streams"] = map[string]any{
		"state":     stream.StateFailed,
		"failed_at": time.Now().UTC().Format(time.RFC3339),
		"reason":    "seeded failed run for the retry leg",
	}
	b, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal doc %s: %v", itemID, err)
	}
	row.Document = b
	if err := w.st.PutItem(ctx, row); err != nil {
		t.Fatalf("persist failed state %s: %v", itemID, err)
	}
}

// gateGet fetches one descriptor through the real router with the world's
// admin bearer and returns the served bytes plus their wire decode.
func gateGet(t *testing.T, w *pbWorld, baseURL, itemID string) ([]byte, gateDescriptor) {
	t.Helper()
	status, body, _ := pbDo(t, w.client, http.MethodGet, baseURL+"/api/v1/items/"+itemID+"/playback", w.token, nil)
	if status != http.StatusOK {
		t.Fatalf("descriptor %s: status %d, want 200 (body=%s)", itemID, status, body)
	}
	var d gateDescriptor
	if err := json.Unmarshal(body, &d); err != nil {
		t.Fatalf("decode descriptor %s: %v (body=%s)", itemID, err, body)
	}
	return body, d
}

// gateStreams reads one item's persisted streams namespace back from the
// store (disk/document truth, never the wire).
func gateStreams(t *testing.T, w *pbWorld, itemID string) map[string]any {
	t.Helper()
	row, err := w.st.GetItem(context.Background(), itemID)
	if err != nil {
		t.Fatalf("re-read item %s: %v", itemID, err)
	}
	var doc struct {
		Streams map[string]any `json:"streams"`
	}
	if err := json.Unmarshal(row.Document, &doc); err != nil {
		t.Fatalf("re-read doc %s: %v", itemID, err)
	}
	return doc.Streams
}

// gateProbeStreams ffprobes one published artifact path (the in-test oracle's
// only I/O) and returns the verbatim -show_streams streams array.
func gateProbeStreams(t *testing.T, path string) []map[string]any {
	t.Helper()
	out, err := exec.Command("ffprobe", "-v", "error", "-show_streams", "-of", "json", path).CombinedOutput()
	if err != nil {
		t.Fatalf("ffprobe %s: %v: %s", filepath.Base(path), err, out)
	}
	var doc struct {
		Streams []map[string]any `json:"streams"`
	}
	if err := json.Unmarshal(out, &doc); err != nil {
		t.Fatalf("ffprobe %s json: %v", filepath.Base(path), err)
	}
	return doc.Streams
}

// gateAvcPrefix is the oracle's restatement of the RFC 6381 avc1.PPCCLL
// prefix constants (profile_idc + constraint byte) — the public specification
// the composition table encodes, restated here so the oracle judges the
// artifact instead of grading the mechanism with itself.
var gateAvcPrefix = map[string]string{
	"Baseline":             "4200",
	"Constrained Baseline": "4240",
	"Main":                 "4D40",
	"High":                 "6400",
}

// gateOracleCodecs derives the published build's expected codec strings from
// the artifact itself: the init segment the SERVED playlist names is probed
// for its sample entries (the MP4 muxer's tags — avc1 video, mp4a audio),
// the published playlist is probed for the profile/level facts a bare init
// does not carry, and the RFC 6381 strings are composed in the test. Videos
// first, then audio — the rendition order the descriptor promises.
func gateOracleCodecs(t *testing.T, buildDir, initURI string) []string {
	t.Helper()
	// The init's sample entries: the artifact truth the record must match.
	initStreams := gateProbeStreams(t, filepath.Join(buildDir, filepath.FromSlash(initURI)))
	var sawVideo, sawAudio bool
	for _, st := range initStreams {
		tag, _ := st["codec_tag_string"].(string)
		switch st["codec_type"] {
		case "video":
			if tag != "avc1" {
				t.Fatalf("published init video sample entry tag = %q, want avc1", tag)
			}
			sawVideo = true
		case "audio":
			if tag != "mp4a" {
				t.Fatalf("published init audio sample entry tag = %q, want mp4a", tag)
			}
			sawAudio = true
		}
	}
	if !sawVideo || !sawAudio {
		t.Fatalf("published init sample entries: video=%t audio=%t, want both", sawVideo, sawAudio)
	}
	// The published playlist carries the profile/level facts (a bare init
	// reports level -99 — the same reason the publish path probes playlists).
	plStreams := gateProbeStreams(t, filepath.Join(buildDir, "index.m3u8"))
	var out []string
	for _, st := range plStreams {
		name, _ := st["codec_name"].(string)
		profile, _ := st["profile"].(string)
		switch name {
		case "h264":
			prefix, ok := gateAvcPrefix[profile]
			if !ok {
				t.Fatalf("oracle cannot compose profile %q (fixture produced an unplanned profile — extend the oracle's RFC table)", profile)
			}
			lv, ok := st["level"].(float64)
			if !ok || lv < 1 || lv > 255 {
				t.Fatalf("published playlist video level = %v, want a usable 1..255 int", st["level"])
			}
			out = append(out, fmt.Sprintf("avc1.%s%02X", prefix, int(lv)))
		case "aac":
			if profile != "LC" {
				t.Fatalf("published playlist audio profile = %q, want LC (the fixture's AAC)", profile)
			}
			out = append(out, "mp4a.40.2")
		default:
			t.Fatalf("published playlist carries unexpected stream %q", name)
		}
	}
	if len(out) != 2 {
		t.Fatalf("oracle composed %v, want exactly [avc1, mp4a] (one video + one embedded audio)", out)
	}
	return out
}

// gateAssertCodecsEqual asserts two codec records are the same non-empty
// ordered list — the ≡ between record, projection, and artifact.
func gateAssertCodecsEqual(t *testing.T, what string, got, want []string) {
	t.Helper()
	if len(got) == 0 {
		t.Fatalf("%s codecs = <empty>, want %v (a servable h264/AAC pack must record its codecs)", what, want)
	}
	if strings.Join(got, "|") != strings.Join(want, "|") {
		t.Fatalf("%s codecs = %v, want the artifact oracle %v", what, got, want)
	}
}

// TestPlaybackCapabilityGateJoint is 5.1's acceptance floor: the three
// cross-group contracts hold over real instances.
func TestPlaybackCapabilityGateJoint(t *testing.T) {
	w := pbNewWorld(t)
	if w.media.OptInCodecs {
		t.Fatal("world opt-in knob must be off (the gate legs' precondition)")
	}
	q := gateNewQueue(t, w)
	enqueue := w.pbEnqueue(q)
	baseURL := gateNewServer(t, w, enqueue)

	// --- fixtures: a real scanned MKV for the pack legs, a seeded knob-off
	// opt-in item for the refusal leg ------------------------------------
	libRoot := filepath.Join(t.TempDir(), "lib")
	show := filepath.Join(libRoot, "Capability Gate Show")
	if err := os.MkdirAll(show, 0o755); err != nil {
		t.Fatalf("mkdir fixture: %v", err)
	}
	pbMakeMKV(t, filepath.Join(show, "Capability Gate Show E01.mkv"), 5*time.Second, false)

	libID := pbCreateLibrary(t, w, "serial", libRoot, "QA Capability Gate")
	res := pbScanLibrary(t, w, libID)
	if res.Discovered != 2 || res.Persisted != 2 {
		t.Fatalf("scan discovered=%d persisted=%d, want 2/2 (1 serial record + 1 episode); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	pbAwaitIdle(t, q, 30*time.Second) // metadata chain soft-fails (plugins unloaded); drain it
	byRel := pbItemByRel(t, w, libID)
	e01, ok := byRel["Capability Gate Show/Capability Gate Show E01.mkv"]
	if !ok || e01.ID == "" {
		t.Fatalf("E01 item missing; have %v", relKeys(byRel))
	}
	gateID := gateSeedItem(t, w, libID, "capability-gate/Hevc-Movie-QA.mkv")

	// --- (c) part 1 — the descriptor's own token (honesty projection,
	// state none): the seeded knob-off opt-in item answers unsupported with
	// codec_not_opted_in through the real router, and the direct answer
	// carries NO codecs key (the field describes the pack, never the floor).
	_, gateDesc := gateGet(t, w, baseURL, gateID)
	if gateDesc.Mode != "direct" || gateDesc.State != "unsupported" {
		t.Fatalf("gate item descriptor = mode %q state %q, want direct/unsupported", gateDesc.Mode, gateDesc.State)
	}
	if string(gateDesc.StateReason) != `"codec_not_opted_in"` {
		t.Fatalf("gate item state_reason = %s, want codec_not_opted_in", gateDesc.StateReason)
	}
	if len(gateDesc.Codecs) != 0 {
		t.Fatalf("gate item direct descriptor carries a codecs value %s, want the key absent", gateDesc.Codecs)
	}

	// --- (a) end-to-end codecs: the real lane publishes; record ≡
	// projection ≡ artifact -----------------------------------------------
	if err := enqueue(e01.ID); err != nil {
		t.Fatalf("enqueue pack %s: %v", e01.ID, err)
	}
	streams := pbAwaitStreams(t, w.st, e01.ID, "complete", 60*time.Second)
	pbAwaitIdle(t, q, 30*time.Second)
	nonce, _ := streams["nonce"].(string)
	if nonce == "" {
		t.Fatalf("persisted streams missing nonce: %v", streams)
	}
	// 2.1's record: the persisted namespace carries the codec record.
	rawRecord, ok := streams["codecs"].([]any)
	if !ok || len(rawRecord) == 0 {
		t.Fatalf("persisted streams codecs = %v, want a non-empty record (2.1's publish-time write)", streams["codecs"])
	}
	record := make([]string, 0, len(rawRecord))
	for _, c := range rawRecord {
		s, ok := c.(string)
		if !ok || s == "" {
			t.Fatalf("persisted codecs entry %v is not a non-empty string", c)
		}
		record = append(record, s)
	}
	// The build dir is the nonce the record was persisted under.
	buildDir := filepath.Join(w.root, e01.ID, nonce)

	// 2.2's projection: the descriptor through the REAL router answers hls
	// with the same ordered strings.
	_, d := gateGet(t, w, baseURL, e01.ID)
	if d.Mode != "hls" || d.State != "complete" {
		t.Fatalf("packed descriptor = mode %q state %q, want hls/complete", d.Mode, d.State)
	}
	var served []string
	if err := json.Unmarshal(d.Codecs, &served); err != nil || len(served) == 0 {
		t.Fatalf("descriptor codecs wire = %s (decode %v), want a non-empty array", d.Codecs, err)
	}

	// The artifact truth: the SERVED playlist names the init; the oracle
	// probes that init's sample entries and the published playlist's facts.
	plStatus, plBody, _ := pbDo(t, w.client, http.MethodGet, baseURL+d.PlayURL, "", nil)
	if plStatus != http.StatusOK {
		t.Fatalf("playlist %s: status %d, want 200", d.PlayURL, plStatus)
	}
	initURI := ""
	for _, l := range strings.Split(string(plBody), "\n") {
		// The FIRST map is the head's plain init reference; the tail merge
		// re-states EXT-X-MAP with its own tokenized copy (the
		// self-authorizing playlist) — the same init bytes on disk.
		if initURI == "" && strings.HasPrefix(strings.TrimSpace(l), "#EXT-X-MAP") {
			if i := strings.Index(l, `URI="`); i >= 0 {
				rest := l[i+len(`URI="`):]
				if j := strings.Index(rest, `"`); j >= 0 {
					initURI = rest[:j]
				}
			}
		}
	}
	if i := strings.Index(initURI, "?"); i >= 0 { // a self-authorizing map carries the token query
		initURI = initURI[:i]
	}
	if initURI == "" {
		t.Fatalf("served playlist carries no EXT-X-MAP init reference:\n%s", plBody)
	}
	oracle := gateOracleCodecs(t, buildDir, initURI)
	gateAssertCodecsEqual(t, "persisted record", record, oracle)
	gateAssertCodecsEqual(t, "served descriptor", served, oracle)
	// The order is the contract: video first, then audio (rendition order).
	if !strings.HasPrefix(served[0], "avc1.") || served[1] != "mp4a.40.2" {
		t.Fatalf("served codecs %v, want [avc1.*, mp4a.40.2] (video first, then audio)", served)
	}

	// --- (b) publish replacement: the repack drives the real lane; exactly
	// ONE build directory survives and the descriptor answers it -----------
	oldPlayURL := d.PlayURL
	if err := enqueue(e01.ID); err != nil {
		t.Fatalf("enqueue repack %s: %v", e01.ID, err)
	}
	pbAwaitIdle(t, q, 60*time.Second) // the repack drained AND persisted (persist precedes idle)
	streams = gateStreams(t, w, e01.ID)
	if state, _ := streams["state"].(string); state != "complete" {
		t.Fatalf("streams state after repack = %q, want complete (%v)", state, streams)
	}
	newNonce, _ := streams["nonce"].(string)
	if newNonce == "" || newNonce == nonce {
		t.Fatalf("repack did not publish a fresh build nonce: old %q, streams %v", nonce, streams)
	}
	// The ON-DISK state: exactly one build directory under the item's
	// artifact root, and it is the new nonce (directory listing, not logs).
	entries, err := os.ReadDir(filepath.Join(w.root, e01.ID))
	if err != nil {
		t.Fatalf("read artifact root %s: %v", filepath.Join(w.root, e01.ID), err)
	}
	var dirs []string
	for _, e := range entries {
		if e.IsDir() {
			dirs = append(dirs, e.Name())
		}
	}
	if len(dirs) != 1 || dirs[0] != newNonce {
		t.Fatalf("build directories under %s = %v, want exactly [%s] (publish replacement)", filepath.Join(w.root, e01.ID), dirs, newNonce)
	}
	// The descriptor answers the NEW build; the superseded playlist URL stops
	// answering; the fresh playlist serves complete.
	_, d2 := gateGet(t, w, baseURL, e01.ID)
	if !strings.Contains(d2.PlayURL, "/"+newNonce+"/index.m3u8?token=") {
		t.Fatalf("play URL after repack = %q, want the fresh nonce's playlist", d2.PlayURL)
	}
	if oldStatus, _, _ := pbDo(t, w.client, http.MethodGet, baseURL+oldPlayURL, "", nil); oldStatus == http.StatusOK {
		t.Fatalf("superseded playlist URL %s still answers 200 after publish replacement", oldPlayURL)
	}
	if plStatus, plBody, _ := pbDo(t, w.client, http.MethodGet, baseURL+d2.PlayURL, "", nil); plStatus != http.StatusOK || !strings.Contains(string(plBody), "#EXT-X-ENDLIST") {
		t.Fatalf("fresh playlist GET: status %d, want 200 with the complete playlist (body %q)", plStatus, plBody)
	}
	// The new build's record ≡ projection ≡ artifact, same oracle.
	rawRecord, ok = streams["codecs"].([]any)
	if !ok || len(rawRecord) == 0 {
		t.Fatalf("persisted codecs after repack = %v, want the fresh build's record", streams["codecs"])
	}
	record = record[:0]
	for _, c := range rawRecord {
		s, _ := c.(string)
		record = append(record, s)
	}
	var served2 []string
	if err := json.Unmarshal(d2.Codecs, &served2); err != nil {
		t.Fatalf("descriptor codecs after repack wire = %s (decode %v)", d2.Codecs, err)
	}
	oracle2 := gateOracleCodecs(t, filepath.Join(w.root, e01.ID, newNonce), initURI)
	gateAssertCodecsEqual(t, "persisted record after repack", record, oracle2)
	gateAssertCodecsEqual(t, "served descriptor after repack", served2, oracle2)

	// --- (c) part 2 — the refusal rides the real router: the item's
	// packaging state is failed (the lane's terminal shape), the same knob is
	// off, and POST /play {retry:true} answers 400 whose error code is the
	// descriptor's own token — one judge, one vocabulary -------------------
	gateFailItem(t, w, gateID)
	status, body, _ := pbDo(t, w.client, http.MethodPost, baseURL+"/api/v1/items/"+gateID+"/play", w.token, map[string]any{"retry": true})
	if status != http.StatusBadRequest {
		t.Fatalf("gate-closed retry: status %d, want 400 (body=%s)", status, body)
	}
	var eb struct {
		Error struct {
			Code      string `json:"code"`
			Message   string `json:"message"`
			Retryable bool   `json:"retryable"`
		} `json:"error"`
	}
	if err := json.Unmarshal(body, &eb); err != nil {
		t.Fatalf("decode refusal body: %v (body=%s)", err, body)
	}
	const wantToken = "codec_not_opted_in"
	if eb.Error.Code != wantToken {
		t.Fatalf("refusal error code = %q, want the gate token %q exactly", eb.Error.Code, wantToken)
	}
	if eb.Error.Retryable {
		t.Fatal("refusal retryable = true, want false (a policy verdict is not transient)")
	}
	// The agreement scenario: the 400's token IS the descriptor's
	// state_reason token for the same seeded item (fetched at state none
	// above, before the failed run was seeded).
	if string(gateDesc.StateReason) != `"`+wantToken+`"` {
		t.Fatalf("descriptor state_reason %s != refusal token %q (one vocabulary broken)", gateDesc.StateReason, wantToken)
	}
	// The refusal changed nothing: the failed state stands, nothing was
	// enqueued (the queue is idle and the floor file would have failed ffmpeg
	// had a pack ever run).
	if got := gateStreams(t, w, gateID); got["state"] != stream.StateFailed {
		t.Fatalf("streams state after refused retry = %v, want failed untouched", got)
	}
	pbAwaitIdle(t, q, 10*time.Second)
}
